INSERT INTO `products` (`id`, `userId`, `title`, `description`, `category`, `price`, `unit`, `region`, `imageUrl`, `isVerified`, `marketplaceType`, `productSource`, `status`, `createdAt`, `updatedAt`) VALUES (77, 1, 'Pioneer Hybrid Corn Seeds (SC 10)', 'SC 10 hybrid corn seeds from Egyptian Agricultural Company. High-yielding variety for Nile Valley conditions. Drought-tolerant with 110-day maturity. Yield 4–5 tonnes/feddan. 1 kg pack.', 'SEEDS', '125.00', 'kg', 'Luxor, Egypt', 'https://organicbazar.net/cdn/shop/files/sweetcornf1hybridseeds_cornseeds_organicbazar_organicbazarseeds_sweetcorn_1.jpg?v=1758347017&width=1946', 1, 'AGRI_MARKET', 'MANUAL', 'AVAILABLE', '2026-05-29 08:14:16', '2026-05-29 08:14:16');
INSERT INTO `products` (`id`, `userId`, `title`, `description`, `category`, `price`, `unit`, `region`, `imageUrl`, `isVerified`, `marketplaceType`, `productSource`, `status`, `createdAt`, `updatedAt`) VALUES (78, 1, 'Hybrid Cucumber Seeds (Beit Alpha)', 'Beit Alpha cucumber hybrid seeds – the most popular cucumber type in Egyptian markets. Parthenocarpic (no pollination required). Smooth, dark green, 15–18cm fruits. 50g pack.', 'SEEDS', '290.00', '50g pack', 'Cairo, Egypt', 'https://m.media-amazon.com/images/I/71v32njQZeL._AC_UF1000,1000_QL80_.jpg', 1, 'AGRI_MARKET', 'MANUAL', 'AVAILABLE', '2026-05-29 08:14:16', '2026-05-29 08:14:16');
INSERT INTO `products` (`id`, `userId`, `title`, `description`, `category`, `price`, `unit`, `region`, `imageUrl`, `isVerified`, `marketplaceType`, `productSource`, `status`, `createdAt`, `updatedAt`) VALUES (79, 1, 'Sunflower Seeds (High-Oil Variety)', 'High-oil content sunflower seeds (45–48% oil) for press and edible oil production. Early maturity (90–95 days), 150–180cm plant height. Suitable for Upper Egypt conditions. 1 kg.', 'SEEDS', '98.00', 'kg', 'Assiut, Egypt', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTYOqH_rseciwwPJ-IT8WdJ8efb38eusXuZfw&s', 1, 'AGRI_MARKET', 'MANUAL', 'AVAILABLE', '2026-05-29 08:14:16', '2026-05-29 08:14:16');
INSERT INTO `products` (`id`, `userId`, `title`, `description`, `category`, `price`, `unit`, `region`, `imageUrl`, `isVerified`, `marketplaceType`, `productSource`, `status`, `createdAt`, `updatedAt`) VALUES (80, 1, 'Onion Seeds (Giza 6 Variety)', 'Giza 6 is Egypt''s most popular dry onion variety. Adapted to Egyptian climate conditions. Medium-large bulbs, yellow-brown skin, high pungency and excellent storage. 100g pack.', 'SEEDS', '78.00', '100g pack', 'Giza, Egypt', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRyW6WNJU55X0vXrKj5phr7M0gkeyraeuWEsA&s', 1, 'AGRI_MARKET', 'MANUAL', 'AVAILABLE', '2026-05-29 08:14:16', '2026-05-29 08:14:16');
INSERT INTO `products` (`id`, `userId`, `title`, `description`, `category`, `price`, `unit`, `region`, `imageUrl`, `isVerified`, `marketplaceType`, `productSource`, `status`, `createdAt`, `updatedAt`) VALUES (97, 1, 'Zar3a Box', 'The Zar3a Box is an Egyptian-made, solar-powered smart sensor placed directly in greenhouse soil that helps farmers easily monitor crop health by displaying live soil pH, moisture, temperature, and humidity on its screen and wirelessly transmitting the data.', 'EQUIPMENT', '20000.00', 'unit', 'Egypt', '/uploads/products/d86f5b83-5498-4126-90ad-9e7aaa6cf0cb.png', 0, 'SENSOR_MARKET', 'MANUAL', 'AVAILABLE', '2026-06-03 20:09:40', '2026-06-03 20:09:40');
INSERT INTO `products` (`id`, `userId`, `title`, `description`, `category`, `price`, `unit`, `region`, `imageUrl`, `isVerified`, `marketplaceType`, `productSource`, `status`, `createdAt`, `updatedAt`) VALUES (99, 79, 'Egyptian mango', 'Egyptian mangoes are renowned for their sweet, juicy flavor, large size, and rich nutritional content, making them a prized fruit both locally and internationally.', 'OTHER', '80.00', 'kg', 'Ismailia, Egypt', 'https://tse2.mm.bing.net/th/id/OIP.tlwdwA4xDZh0RPFHUa-uBgHaEK?rs=1&pid=ImgDetMain&o=7&rm=3', 0, 'CROP_MARKET', 'MANUAL', 'AVAILABLE', '2026-06-05 20:53:38', '2026-06-05 20:53:38');
